CREATE POLICY "Company admins can insert audit logs" ON public.audit_logs FOR INSERT TO authenticated WITH CHECK ((has_role(auth.uid(), 'company_admin'::app_role) AND (actor_id = auth.uid())));
CREATE POLICY "Company admins can view audit logs" ON public.audit_logs FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Service role can insert audit logs" ON public.audit_logs FOR INSERT TO service_role WITH CHECK (true);
CREATE POLICY "Anon users can view prices" ON public.current_prices FOR SELECT TO anon USING (true);
CREATE POLICY "Authenticated users can view prices" ON public.current_prices FOR SELECT TO authenticated USING (true);
CREATE POLICY "Anyone can view snapshots" ON public.daily_price_snapshots FOR SELECT TO public USING (true);
CREATE POLICY "Analysts can insert own plans" ON public.expert_plans FOR INSERT TO authenticated WITH CHECK ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Analysts can update own plans" ON public.expert_plans FOR UPDATE TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Analysts can view own plans" ON public.expert_plans FOR SELECT TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Anyone can view approved active plans" ON public.expert_plans FOR SELECT TO public USING (((is_active = true) AND (review_status = 'approved'::plan_review_status)));
CREATE POLICY "Company admins full access plans" ON public.expert_plans FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Subscribers can view subscribed plans" ON public.expert_plans FOR SELECT TO authenticated USING (is_subscribed_to_plan(auth.uid(), id));
CREATE POLICY "Analysts manage own signal legs" ON public.expert_signal_legs FOR ALL TO authenticated USING ((EXISTS ( SELECT 1    FROM (expert_signals s      JOIN experts e ON ((e.id = s.expert_id)))   WHERE ((s.id = expert_signal_legs.signal_id) AND (e.user_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1    FROM (expert_signals s      JOIN experts e ON ((e.id = s.expert_id)))   WHERE ((s.id = expert_signal_legs.signal_id) AND (e.user_id = auth.uid())))));
CREATE POLICY "Company admins full access signal legs" ON public.expert_signal_legs FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Subscribers can view published signal legs" ON public.expert_signal_legs FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1    FROM expert_signals s   WHERE ((s.id = expert_signal_legs.signal_id) AND (s.status = 'published'::signal_status) AND (s.expert_id IN ( SELECT has_active_subscription_after.expert_id            FROM has_active_subscription_after(auth.uid(), s.published_at) has_active_subscription_after(expert_id)))))));
CREATE POLICY "Analysts can delete own signals" ON public.expert_signals FOR DELETE TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Analysts can insert own signals" ON public.expert_signals FOR INSERT TO authenticated WITH CHECK ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Analysts can update own signals" ON public.expert_signals FOR UPDATE TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Analysts can view own signals" ON public.expert_signals FOR SELECT TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Company admins full access signals" ON public.expert_signals FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Subscribers can view signals published after subscription start" ON public.expert_signals FOR SELECT TO public USING (((status = 'published'::signal_status) AND (expert_id IN ( SELECT has_active_subscription_after.expert_id    FROM has_active_subscription_after(auth.uid(), expert_signals.published_at) has_active_subscription_after(expert_id)))));
CREATE POLICY "Analysts can update own expert" ON public.experts FOR UPDATE TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Analysts can view own expert" ON public.experts FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Anyone can view active experts" ON public.experts FOR SELECT TO public USING (((status = 'active'::text) OR ((status = 'draft'::text) AND is_tester(auth.uid()))));
CREATE POLICY "Company admins full access experts" ON public.experts FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Subscribers can view subscribed experts" ON public.experts FOR SELECT TO authenticated USING (((id IN ( SELECT has_active_subscription.expert_id    FROM has_active_subscription(auth.uid()) has_active_subscription(plan_id, expert_id))) AND ((status = 'active'::text) OR is_tester(auth.uid()))));
CREATE POLICY "fx_rates read for everyone" ON public.fx_rates FOR SELECT TO public USING (true);
CREATE POLICY "Company admins can insert fix proposals" ON public.holdings_fix_proposals FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Company admins can update fix proposals" ON public.holdings_fix_proposals FOR UPDATE TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Company admins can view fix proposals" ON public.holdings_fix_proposals FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Analysts can view own plan subscriptions" ON public.member_subscriptions FOR SELECT TO authenticated USING ((plan_id IN ( SELECT ep.id    FROM (expert_plans ep      JOIN experts e ON ((ep.expert_id = e.id)))   WHERE (e.user_id = auth.uid()))));
CREATE POLICY "Company admins full access subscriptions" ON public.member_subscriptions FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Users can update own subscription preferences" ON public.member_subscriptions FOR UPDATE TO authenticated USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users can view own subscriptions" ON public.member_subscriptions FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Company admins full access providers" ON public.payment_providers FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Company admins can view all profiles" ON public.profiles FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Users can insert own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can update own profile" ON public.profiles FOR UPDATE TO authenticated USING ((auth.uid() = user_id));
CREATE POLICY "Users can view own profile" ON public.profiles FOR SELECT TO authenticated USING ((auth.uid() = user_id));
CREATE POLICY "Company admins can view signal trade applications" ON public.signal_trade_applications FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Anyone can read stock names" ON public.stock_names FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Admins full access target history" ON public.target_price_history FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Users insert own target history" ON public.target_price_history FOR INSERT TO authenticated WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users view own target history" ON public.target_price_history FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Analysts can delete own trade records" ON public.trade_records FOR DELETE TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Analysts can view own trades" ON public.trade_records FOR SELECT TO authenticated USING ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.user_id = auth.uid()))));
CREATE POLICY "Anyone can view closed trades for active experts" ON public.trade_records FOR SELECT TO public USING (((status = ANY (ARRAY['closed'::trade_status, 'stopped'::trade_status])) AND ((expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.status = 'active'::text))) OR is_tester(auth.uid()))));
CREATE POLICY "Anyone can view open trades for active experts" ON public.trade_records FOR SELECT TO public USING (((status = 'open'::trade_status) AND (expert_id IN ( SELECT experts.id    FROM experts   WHERE (experts.status = 'active'::text)))));
CREATE POLICY "Company admins can delete trade records" ON public.trade_records FOR DELETE TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Company admins can view all trades" ON public.trade_records FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Subscribers can view subscribed expert trades" ON public.trade_records FOR SELECT TO authenticated USING ((expert_id IN ( SELECT has_active_subscription.expert_id    FROM has_active_subscription(auth.uid()) has_active_subscription(plan_id, expert_id))));
CREATE POLICY "tw_bsr_authenticated_read" ON public.tw_bsr_daily FOR SELECT TO authenticated USING (true);
CREATE POLICY "company_admin_can_read_bsr_queue" ON public.tw_bsr_sync_queue FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "service_role_manages_bsr_queue" ON public.tw_bsr_sync_queue FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY "admins manage holidays" ON public.tw_market_holidays FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "holidays readable by everyone" ON public.tw_market_holidays FOR SELECT TO public USING (true);
CREATE POLICY "Analysts can delete own user performances" ON public.user_performances FOR DELETE TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Analysts can view own user performances" ON public.user_performances FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Company admins can delete user performances" ON public.user_performances FOR DELETE TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Users can insert own user performances" ON public.user_performances FOR INSERT TO authenticated WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users can update own user performances" ON public.user_performances FOR UPDATE TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Company admins can manage roles" ON public.user_roles FOR ALL TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Company admins can view all roles" ON public.user_roles FOR SELECT TO authenticated USING (has_role(auth.uid(), 'company_admin'::app_role));
CREATE POLICY "Users can view own roles" ON public.user_roles FOR SELECT TO authenticated USING ((auth.uid() = user_id));

